import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.Boholvbs.js";const p=JSON.parse('{"title":"nanoMuse brand","description":"","frontmatter":{},"headers":[],"relativePath":"brand.md","filePath":"brand.md"}'),r={name:"brand.md"};function n(i,e,s,c,h,l){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="nanomuse-brand" tabindex="-1">nanoMuse brand <a class="header-anchor" href="#nanomuse-brand" aria-label="Permalink to &quot;nanoMuse brand&quot;">​</a></h1><p>Decided 2026-09-24. The app icon and the in-app colour system are one decision: the palette is derived from the icon so the whole app matches the tile on the home screen.</p><h2 id="the-mark" tabindex="-1">The mark <a class="header-anchor" href="#the-mark" aria-label="Permalink to &quot;The mark&quot;">​</a></h2><p>One continuous pen stroke that reads as an <strong>N</strong>: a hooked entry, one rounded peak, a long diagonal, a tight valley, and an upward exit. It follows the same visual grammar as Muse&#39;s single-stroke mark (Muse&#39;s is an M with three arches; ours is an N with one) — the same way OpenManus rhymes with Manus while being a different gesture. The mark is abstract on purpose: it is a gesture first and a letter second.</p><ul><li>Source of truth: <code>assets/brand/nanomuse-icon-source-1024.png</code> (final render, white squircle on brand blue). Everything else is derived from it.</li><li><code>assets/brand/nanomuse-mark.svg</code> — the stroke alone, traced as a single filled path, viewBox <code>0 0 100 100</code> in tile coordinates, gradient fill.</li><li><code>assets/brand/nanomuse-icon.svg</code> — white squircle tile (<code>rx=27</code>) + mark. This is the app icon.</li><li><code>assets/brand/nanomuse-icon-on-blue.svg</code> — the icon on the brand-blue backdrop, for store listings and the splash only. Wherever the icon stands for the app — README, site, social card, favicon — it is the plain tile: white, the mark, a hairline edge, no backdrop.</li><li><code>assets/brand/nanomuse-mark-rgba-688.png</code> — the stroke with alpha, 688 px, raster fallback.</li><li><code>docs/app-icon.png</code> — the tile rendered with rounded corners (27 % radius, transparent outside, a hairline <code>#D9D9DE</code> edge so it keeps its shape on white), 512 px: the icon as it sits on a home screen. This is the README hero and the picture to use wherever the app is shown as an app.</li></ul><p>The icon is <strong>not</strong> the mascot. The default face is the bundled <strong>dragon</strong> (<code>web/public/avatars/</code>, the Android app&#39;s <code>avatar/</code>); the red panda (<code>web/src/components/redPandaShapes.ts</code>) is one of the optional avatars a user can pick. Never put the red panda (or the dragon) on the launcher icon, and never put the N mark in the chat as a face.</p><h2 id="colour" tabindex="-1">Colour <a class="header-anchor" href="#colour" aria-label="Permalink to &quot;Colour&quot;">​</a></h2><p>Measured from the icon.</p><table tabindex="0"><thead><tr><th>Token</th><th>Value</th><th>Use</th></tr></thead><tbody><tr><td><code>brand.stroke.start</code></td><td><code>#015CFB</code></td><td>left end of the mark&#39;s gradient</td></tr><tr><td><code>brand.stroke.end</code></td><td><code>#0186FB</code></td><td>right end of the mark&#39;s gradient</td></tr><tr><td><code>brand.blue</code></td><td><code>#0078FD</code></td><td>backdrop behind the tile; splash; hero backgrounds</td></tr><tr><td><code>tile</code></td><td><code>#FFFFFF</code></td><td>icon tile</td></tr></tbody></table><h3 id="light-theme" tabindex="-1">Light theme <a class="header-anchor" href="#light-theme" aria-label="Permalink to &quot;Light theme&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Token</th><th>Value</th><th>Contrast</th><th>Use</th></tr></thead><tbody><tr><td><code>primary</code></td><td><code>#015CFB</code></td><td>5.35 on white</td><td>links, primary buttons (white text), active tab, send button, status line</td></tr><tr><td><code>primary.container</code></td><td><code>#E5F0FF</code></td><td>—</td><td>user bubble, selected rows, chips</td></tr><tr><td><code>primary.tint</code></td><td><code>#EEF5FF</code></td><td>—</td><td>subtle highlighted surfaces</td></tr><tr><td><code>bg.grouped</code></td><td><code>#F2F2F7</code></td><td>—</td><td>page background (unchanged from OpenMinis)</td></tr><tr><td><code>surface</code></td><td><code>#FFFFFF</code></td><td>—</td><td>cards, input</td></tr></tbody></table><h3 id="dark-theme" tabindex="-1">Dark theme <a class="header-anchor" href="#dark-theme" aria-label="Permalink to &quot;Dark theme&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Token</th><th>Value</th><th>Contrast</th><th>Use</th></tr></thead><tbody><tr><td><code>primary</code></td><td><code>#58A6FF</code></td><td>8.3 on <code>#000</code>, 6.7 on <code>#1C1C1E</code></td><td>links, buttons (black text), active tab, status line</td></tr><tr><td><code>primary.container</code></td><td><code>#1A2B4A</code></td><td>—</td><td>user bubble</td></tr><tr><td><code>bg</code> / <code>surface</code> / <code>surface.2</code></td><td><code>#000000</code> / <code>#1C1C1E</code> / <code>#2C2C2E</code></td><td>—</td><td>unchanged from OpenMinis</td></tr></tbody></table><p>Rules: one accent hue only. Code blocks, thinking text and links that OpenMinis coloured with iOS blue, orange and green become <code>primary</code> plus neutrals. Rust orange from the red panda stays inside the avatar; it is not a UI colour.</p><h2 id="android-mapping-done-in-s1" tabindex="-1">Android mapping (done in S1) <a class="header-anchor" href="#android-mapping-done-in-s1" aria-label="Permalink to &quot;Android mapping (done in S1)&quot;">​</a></h2><ul><li>Adaptive icon: background layer = solid <code>#FFFFFF</code>; foreground layer = the mark as a <code>VectorDrawable</code> whose <code>fillColor</code> is the two-stop linear gradient above; monochrome layer = the same path with a flat fill (Android tints it).</li><li>Icon skins (activity aliases kept from OpenMinis): <em>Auto</em> = white tile; <em>Light</em> = white tile; <em>Dark</em> = <code>#0F1B33</code> tile with a white mark.</li><li>Notification small icon: the mark, flat white, 24 dp.</li><li>Never ship the old OpenMinis icon, name or the letter-n drafts.</li></ul><h2 id="don-ts" tabindex="-1">Don&#39;ts <a class="header-anchor" href="#don-ts" aria-label="Permalink to &quot;Don&#39;ts&quot;">​</a></h2><ul><li>Don&#39;t recolour the mark outside the blue gradient / flat white / flat black.</li><li>Don&#39;t rotate, outline, or add a shadow to the stroke.</li><li>Don&#39;t place the mark on the brand blue without the white tile (contrast).</li><li>Don&#39;t use Meta&#39;s Muse mark, name or blue as an asset; the kinship is in the gesture only.</li></ul>',18)])])}const b=t(r,[["render",n]]);export{p as __pageData,b as default};
